"""Connect explicit product identities to existing same-plan policy sources.
Links are navigation aids; they never change coverage, PA, preference, or approval.
"""
import re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def norm(s):return re.sub('[^a-z0-9]+',' ',s.lower()).strip()

def attach_provider_policies(data):
 policies={p['id']:p for p in data['policies']}
 # These identities are explicitly named as covered products in the archived policy text.
 ach_aliases={
  'AZ.CP.PMN.05':['rifapentine','Priftin'],
  'AZ.CP.PHAR.1020':['Lemtrada','mitoxantrone'],
  'AZ.CP.PHAR.228':['Herceptin','Herceptin Hylecta','trastuzumab','trastuzumab-hyaluronidase-oysk'],
  'AZ.CP.PMN.1002':['rabeprazole','Aciphex','dexlansoprazole','Dexilant','esomeprazole strontium','Nexium 24HR','omeprazole sodium bicarbonate','Zegerid'],
 }
 for p in policies.values():
  if p['planId']=='az-complete-health':
   if p['id']=='ach-current-policy-5':
    text=(ROOT/'dist'/p['sourceTextUrl'].lstrip('./')).read_text()
    assert 'Reference Number: AZ. CP.PHAR.493' in text
    p['policyCode']='AZ.CP.PHAR.493';p['searchAliases']=['AZ.CP.PHAR.493','Infusion Site of Care Optimization']
   if p['policyCode'] in ach_aliases:p['searchAliases']=list(dict.fromkeys(p.get('searchAliases',[])+ach_aliases[p['policyCode']]))
 count=0;records=set()
 for r in data['medications']:
  if r['planId'] not in ('uhc-community-az','az-complete-health'):continue
  # Reference-brand labels do not establish that a particular branded formulation is covered.
  identities=[norm(r['name'])]
  if r.get('baselineSource'):
   identities.append(norm(re.sub(r'\[[^]]+\]','',r['name'])))
   identities += [norm(v) for v in re.findall(r'\[([^]]+)\]',r['name'])]
  for p in policies.values():
   if p['planId']!=r['planId']:continue
   if r['planId']=='az-complete-health' and p['policyCode'] not in ach_aliases:continue
   aliases=p.get('searchAliases',[])
   matches=[a for a in aliases if len(norm(a))>=5 and any(i==norm(a) or i.startswith(norm(a)+' ') for i in identities)]
   if not matches:continue
   if not p.get('sourceTextUrl') or not p.get('sourcePage'):continue
   textpath=ROOT/'dist'/p['sourceTextUrl'].lstrip('./');assert textpath.is_file()
   link=dict(policyId=p['id'],title=p['name'],policyCode=p['policyCode'],firstPage=p['sourcePage'],lastPage=p.get('sourceLastPage',p['sourcePage']),url=p['sourceUrl'],textUrl=p['sourceTextUrl'],effective=p.get('policyEffective') or p.get('sourceEffective',''),matchedProduct=matches[0],scope='Related same-plan source; verify formulation, indication, age, and authorization branch.')
   links=r.setdefault('policySources',[])
   if not any(x.get('policyId')==p['id'] for x in links):links.append(link);count+=1;records.add(r['id'])
 # Exact Banner November source branches independently reviewed against the
 # archived text and October formulary rows. These are navigation bindings,
 # not new benefit flags or a machine-generated approval algorithm.
 banner_reviewed = {
  "banner-full-3896cdde40e8e8a1": ("banner-policy-12-237", "GL-396211", "Mvasi", "BEVACIZUMAB-AWWB INJECTION", "Mvasi (Bevacizumab-awwb) Injection", "The named October 2025 guideline identifies Mvasi and Zirabev as preferred. The October 2026 formulary does not specify preference for this row. Exact package eligibility is unverified."),
  "banner-full-6c72cfb332a399ef": ("banner-policy-12-237", "GL-396211", "Zirabev", "BEVACIZUMAB-BVZR INJECTION", "Zirabev (Bevacizumab-bvzr) Injection", "The named October 2025 guideline identifies Mvasi and Zirabev as preferred. The October 2026 formulary does not specify preference for this row. Exact package eligibility is unverified."),
  "banner-full-96013cd1d8204447": ("banner-policy-12-1754", "GL-99771", "generic bexarotene caps", "BEXAROTENE CAPSULES", "Bexarotene Capsules (Banner Formulary)", "The named guideline includes both capsules and Targretin gel. This formulary row is capsules only. Separate CTCL and NCCN initial and renewal criteria apply; gel coverage is not established by this row."),
  "banner-full-04d6c166dbdc7a8a": ("banner-policy-12-1422", "GL-700354", "generic bosentan tablet for", "BOSENTAN TABLETS SOLUBLE", "Bosentan Tablets for Oral Suspension (Tracleer Reference)", "The September 2026 guideline identifies generic tablets for oral suspension as preferred, but brand Tracleer and generic conventional tablets as nonpreferred. Exact brand/package eligibility is unverified."),
  'banner-full-df471ac18a4edcdf': ('banner-policy-12-1422', 'GL-700354', 'generic ambrisentan', 'AMBRISENTAN TABLETS', 'Ambrisentan Tablets (Letairis Reference)', 'The September 1 policy identifies generic ambrisentan as preferred and brand Letairis as nonpreferred. The October formulary lists ambrisentan tablets with Letairis as the reference brand. Exact brand/package eligibility is unverified.'),
  'banner-full-42e11b3c0513cedb': ('banner-policy-12-259', 'GL-99541', 'generic anastrozole', 'ANASTROZOLE TABLETS', 'Anastrozole Tablets (Arimidex Reference)', 'The October formulary lists PA and does not specify preference. The named policy has a breast cancer branch and separate NCCN initial and renewal branches; review the applicable branch.'),
 }
 found_banner=set()
 for r in data['medications']:
  if r['id'] not in banner_reviewed:continue
  pid,code,product,original,label,note=banner_reviewed[r['id']]
  assert r['planId']=='banner-ufc' and r['name']==original and r['pa']=='required'
  p=policies[pid];assert p['planId']=='banner-ufc'
  raw=(ROOT/'dist'/p['sourceTextUrl'].lstrip('./')).read_text()
  assert code in raw and product.lower() in ' '.join(raw.lower().split())
  link=dict(policyId=pid,title=p['name'],policyCode=code,firstPage=p['sourcePage'],lastPage=p.get('sourceLastPage',p['sourcePage']),url=p['sourceUrl'],textUrl=p['sourceTextUrl'],effective=p.get('policyEffective') or p.get('sourceEffective',''),matchedProduct=product,scope='Named same-plan policy; review the applicable product, indication and stage.')
  links=r.setdefault('policySources',[])
  if not any(x.get('policyId')==pid or x.get('textUrl')==link['textUrl'] for x in links):links.insert(0,link);count+=1;records.add(r['id'])
  r['reviewedPresentation']={'separate':True,'label':label,'note':note}
  found_banner.add(r['id'])
 assert found_banner==set(banner_reviewed), 'Missing reviewed Banner formulary row'
 # Exact source rows with reviewed named policy; retain existing renderer presentation.
 banner_exact_links = {
  "banner-full-719caae0c9978dca": ("banner-policy-12-945", "GL-322197", "Infliximab (Janssen manufacturer)", "INFLIXIMAB SOLUTION RECONSTITUTED", "required", "preferred", "GL-322197 effective August 2025 names preferred Janssen infliximab NDC 57894016001: 14 initial and renewal branches, 6 and 12 months respectively; sarcoidosis explicitly off-label. Payer prints Janssen authorized biosimilar only; manufacturer identifies same BLA as Remicade, not separately licensed biosimilar. 100 mg IV powder vial, distinct from brand Remicade and SC products. NDC-level reference is not patient payment guarantee."),
  "banner-full-a6e3c12492730c31": ("banner-policy-12-305", "GL-734190", "Aimovig", "ERENUMAB-AOOE SOLN AUTO-INJ", "required", "preferred", "GL-734190 effective October 2026: adult migraine prevention initial 6 months, renewal 12 months. Ajovy-only pediatric alternative excluded. October PDL prints AMOVIG, preferred PA and 3 / 90 quantity. Label 70 or 140 mg/mL SC autoinjector; constipation, hypertension and Raynaud risk. Exact package and syringe eligibility unverified."),
  "banner-full-7112927146512ad5": ("banner-policy-12-1798", "GL-525300", "generic eltrombopag tablet", "ELTROMBOPAG OLAMINE TABLET", "required", "preferred", "GL-525300 effective April 2026 names generic tablets preferred: chronic ITP 12 months, severe aplastic anemia and chronic hepatitis C-associated thrombocytopenia 6 months, initial and renewal separately. Nonpreferred-only steps do not apply to this preferred generic. Label boxed hepatic decompensation/hepatotoxicity; not indicated for MDS. Distinct from powder and Alvaiz. Exact package unverified."),
  "banner-full-28415ec20645c82d": ("banner-policy-12-33", "GL-525274", "Hadlima", "ADALIMUMAB-BWWD SOLN AUTO-INJ", "required", "preferred", "GL-525274 effective March 2026 preferred Hadlima: 15 named initial/renewal branches, NDC-level approval. Policy page 46 lists Hadlima Push NDC 78206018701 (40 mg/0.4 mL) and 78206018401 (40 mg/0.8 mL); no patient payment guarantee. FDA label: institutional vial required for weight-based pediatric JIA below 30 kg or Crohn disease below 40 kg; UC, HS and uveitis adult indications. Boxed serious infection and malignancy risk. Do not transfer to unbranded or syringe listings."),
  "banner-full-84b2d91ea0a7c4f1": ("banner-policy-12-1798", "GL-525300", "Brand Promacta tablet", "ELTROMBOPAG OLAMINE TABLET", "required", "preferred", "Payer conflict: October 2026 PDL lists Promacta tablets brand only, preferred, PA required; GL-525300 effective April 2026 pages 1798–1802 lists brand tablets nonpreferred with additional generic eltrombopag prerequisite. Current criteria and exact package eligibility unverified; do not infer denial or transfer generic tablet or preferred powder criteria."),
  "banner-full-7c98df91d2b8f9ad": ("banner-policy-12-33", "GL-525274", "Hulio", "ADALIMUMAB-FKJP PREFILLED SYRINGE KIT", "required", "preferred", "Payer conflict: October 2026 PDL lists Hulio brand only, preferred, PA required; GL-525274 effective March 2026 page 45 lists Hulio nonpreferred and not approved at that time. Current criteria and exact package eligibility unverified; do not infer denial or transfer autoinjector or other biosimilar criteria."),
  "banner-full-649d84d33fb33d42": ("banner-policy-12-33", "GL-525274", "Hulio", "ADALIMUMAB-FKJP AUTO-INJECTOR KIT", "required", "preferred", "Payer conflict: October 2026 PDL lists Hulio brand only, preferred, PA required; GL-525274 effective March 2026 page 45 lists Hulio nonpreferred and not approved at that time. Current criteria and exact package eligibility unverified; do not infer denial or transfer syringe or other biosimilar criteria."),
  "banner-full-3880bff4a3b70b55": ("banner-policy-12-33", "GL-525274", "Hadlima", "ADALIMUMAB-BWWD SOLN PREF SYR", "required", "preferred", "Payer identity hold: October 2026 PDL lists authorized unbranded biosimilar only, preferred, PA required. GL-525274 effective March 2026 names Hadlima and separately unbranded adalimumab-fkjp (Biocon), not unbranded adalimumab-bwwd. Exact product-specific criteria and package eligibility unverified; do not transfer the fkjp or branded pathway."),
  "banner-full-c50d5a831e1c6a83": ("banner-policy-12-82", "GL-731221", "Aralast NP", "ALPHA1-PROTEINASE INHIBITOR (HUMAN) SOLUTION", "required", "not_specified", "GL-731221 effective October 2026 names Aralast NP. FDA label 0.5 g and 1 g powder vials require reconstitution; payer SOLUTION wording is not a ready-to-infuse presentation. Exact package eligibility unverified."),
  "banner-full-b9c82fb411440f4c": ("banner-policy-12-351", "GL-356254", "cidofovir inj", "CIDOFOVIR IV", "required", "not_specified", "GL-356254 effective September 2025 names cidofovir injection, 12 months, stage not separately labeled. FDA label IV infusion only, NOT intraocular injection; severe renal toxicity risk, requires probenecid and IV saline prehydration. Reference brand not proof of brand/package eligibility."),
  "banner-full-514f1b7852e793e4": ("banner-policy-12-449", "GL-99559", "demeclocycline", "DEMECLOCYCLINE HCL TABLETS", "required", "not_specified", "GL-99559 effective December 2021 names demeclocycline; 6 months per note, stage not separately labeled. FDA label infection indications; no labeled SIADH indication. Do not infer SIADH-specific payer approval from specialist alternative. Exact package eligibility unverified."),
  "banner-full-655161387e7d56c9": ("banner-policy-12-87", "GL-109871", "generic donepezil", "DONEPEZIL HYDROCHLORIDE ORALLY DISINTEGRATING TABLETS", "required", "not_specified", "GL-109871 effective July 2022 names Aricept and generic donepezil for Alzheimer-type dementia, 12 months, stage not separately labeled; separate ODT payer restrictions not printed. FDA label oral disintegrating tablets 5 and 10 mg; not a patch. Exact brand/package eligibility unverified."),
  "banner-full-5871af4cc5e1eb9b": ("banner-policy-12-597", "GL-99455", "Premarin", "ESTROGENS, CONJUGATED VAGINAL CREAM", "required", "not_specified", "GL-99455 effective December 2021 names Premarin for atrophic vaginitis and kraurosis vulvae, 12 months, stage not separately labeled. FDA label vaginal cream 0.625 mg/g also includes menopausal dyspareunia; separate dyspareunia-only payer approval not established. Do not transfer oral/systemic formulation or Femring policy. Exact package eligibility unverified."),
  "banner-full-150d0a331d6c46df": ("banner-policy-12-82", "GL-731221", "Prolastin-C", "ALPHA1-PROTEINASE INHIBITOR (HUMAN) SOLUTION", "required", "not_specified", "Exact covered brand, formulation and package are unverified. GL-731221 effective October 2026 names Prolastin-C, Prolastin-C liquid and Glassia with shared initial and renewal criteria at pages 82–83. Payer combines aliases; lyophilized powder requiring reconstitution and ready solutions remain distinct. Do not infer specific package or automatic product-specific criteria."),
  "banner-full-7c9407dc50aeffd6": ("banner-policy-12-1900", "GL-731217", "Starjemza SC", "USTEKINUMAB-HMNY SOLN PREF SYR", "required", "not_specified", "GL-731217 effective October 2026 names Starjemza preferred; October PDL preference unspecified and PA required. SC syringe 45 mg/0.5 mL or 90 mg/mL; not IV induction. Plaque psoriasis and PsA age 6 and older per label. For IBD, SC maintenance follows IV induction; the payer age 2 and older criterion does not establish labeled pediatric IBD use (available October 2025 label: adult IBD only). Exact package eligibility unverified."),
  "banner-full-d2638c75bf2c5094": ("banner-policy-12-351", "GL-356254", "generic valganciclovir tabs/oral soln", "VALGANCICLOVIR HCL SOLUTION", "required", "not_specified", "GL-356254 effective September 2025 names Valcyte and generic valganciclovir tablets/oral solution, 12 months, stage not separately labeled. FDA label 50 mg/mL after pharmacist preparation; adults use tablets per label. Renal adjustment; boxed hematologic, reproductive and genotoxic risks. Exact brand/package eligibility unverified."),
  "banner-full-e859b1c3f1be58db": ("banner-policy-12-351", "GL-356254", "generic valganciclovir tabs/oral soln", "VALGANCICLOVIR HCL TABLETS", "required", "not_specified", "GL-356254 effective September 2025 names Valcyte and generic valganciclovir tablets/oral solution, 12 months, stage not separately labeled. FDA label 450 mg tablets; distinct from oral solution. Renal adjustment; boxed hematologic, reproductive and genotoxic risks. Exact brand/package eligibility unverified."),
  "banner-full-6d23af5aca74fca8": ("banner-policy-12-194", "GL-731211", "Brand Vfend Powder for Oral Suspension", "VORICONAZOLE SUSPENSION", "required", "not_specified", "GL-731211 effective October 2026 names brand and generic suspension; October PDL brand only, PA required, preference unspecified. Generic policy membership does not establish generic benefit. FDA label 40 mg/mL after reconstitution; distinct from tablets and IV form. Separate named fungal infection and all-other-diagnosis branches; exact package eligibility unverified."),
  "banner-full-9c89c762ecf4a4e7": ("banner-policy-12-1900", "GL-731217", "Starjemza SC", "USTEKINUMAB-HMNY SOLUTION", "required", "not_specified", "SAFETY: payer solution listing does not establish SC versus IV. FDA label SC vial 45 mg/0.5 mL and IV vial 130 mg/26 mL for IBD induction are distinct; do not substitute. GL-731217 effective October 2026 names Starjemza SC and SC/IV at pages 1900–1905, but exact payer vial/route and applicable branch remain unverified. Payer pediatric IBD age does not establish FDA labeling."),
  "banner-full-4ea1555b6e50ad9b": ("banner-policy-12-1321", "GL-731214", "generic dasatinib", "DASATINIB TABLETS", "required", "not_specified", "GL-731214 effective October 2026 names brand Sprycel and generic dasatinib: NCCN category 1, 2A or 2B, 12 months; stage not separately labeled. No Gleevec/Imkeldi-specific payer step. FDA label swallow tablets whole; myelosuppression risk. Exact brand/package eligibility unverified."),
  "banner-full-744c182ca2569adb": ("banner-policy-12-129", "GL-620204", "Anzemet", "DOLASETRON MESYLATE TABLETS", "required", "not_specified", "GL-620204 effective June 2026 names Anzemet for chemotherapy, radiotherapy and postoperative nausea/vomiting. FDA oral tablet label is limited to prevention of moderately emetogenic chemotherapy-induced nausea/vomiting in age 2 and older; other payer indications are not labeled for tablets. QT, PR and QRS prolongation risk. Granisol-only requirements do not apply. Exact brand/package unverified."),
  "banner-full-b744ae9803f287da": ("banner-policy-12-581", "GL-325192", "Retacrit", "EPOETIN ALFA-EPBX SOLUTION", "required", "preferred", "GL-325192 effective August 2025 names Retacrit preferred; October 2026 PDL brand only, preferred, PA required. Separate CKD, zidovudine, chemotherapy, surgery, MDS, HCV and other off-label criteria. HCV renewal note: 12 months or full ribavirin course if response. MDS and HCV are not FDA-labeled indications. FDA boxed cardiovascular, thrombotic and tumor progression risks; payer Hgb/Hct thresholds are NOT treatment targets. Exact package unverified."),
  "banner-full-0865865cc9f5fed9": ("banner-policy-12-1557", "GL-629212", "generic eszopiclone", "ESZOPICLONE", "conditional", "preferred", "October conditional PA: age under 6 or greater than one hypnotic in 30 days. GL-629212 names generic eszopiclone preferred; brand Lunesta nonpreferred with separate step requirements. Printed 30 per 30 days retained. Stage not separately labeled. FDA boxed complex sleep behaviors; pediatric safety and efficacy not established. Exact brand/package unverified."),
  "banner-full-0a392c206a4c7134": ("banner-policy-12-1321", "GL-731214", "etoposide capsules", "ETOPOSIDE CAPSULES", "required", "not_specified", "GL-731214 effective October 2026 names oral etoposide capsules: NCCN category 1, 2A or 2B, 12 months; stage not separately labeled. Do not apply injectable oncology GL-731215 to capsules. FDA label oral capsule; myelosuppression risk. Exact package unverified."),
  "banner-full-7f9d539620cb5752": ("banner-policy-12-259", "GL-99541", "generic exemestane", "EXEMESTANE TABLETS", "required", "not_specified", "GL-99541 effective December 2021 names brand Aromasin and generic exemestane; breast cancer branch, and separate NCCN initial/renewal branches. Do not transfer Arimidex/Fareston-specific criteria. FDA label oral aromatase inhibitor. Exact brand/package unverified."),
  "banner-full-b6f0f769c82aaeea": ("banner-policy-12-1321", "GL-731214", "Caprelsa", "VANDETANIB TABLETS", "required", "not_specified", "GL-731214 effective 2026-10-01 names Caprelsa: NCCN category 1, 2A or 2B, 12 months; stage not separately labeled. No imatinib-specific step. Reference brand does not establish exact brand/generic package eligibility. FDA label boxed QT prolongation, torsades and sudden death risk."),
  "banner-full-4b852a28d521d828": ("banner-policy-12-1321", "GL-731214", "Zelboraf", "VEMURAFENIB TABLETS", "required", "not_specified", "GL-731214 effective 2026-10-01 names Zelboraf: NCCN category 1, 2A or 2B, 12 months; stage not separately labeled. No imatinib-specific step. Reference brand does not establish exact brand/generic package eligibility. FDA label not indicated for wild-type BRAF melanoma."),
  "banner-full-237950cc08ca1717": ("banner-policy-12-1321", "GL-731214", "Zolinza", "VORINOSTAT CAPSULES", "required", "not_specified", "GL-731214 effective 2026-10-01 names Zolinza: NCCN category 1, 2A or 2B, 12 months; stage not separately labeled. No imatinib-specific step. Reference brand does not establish exact brand/generic package eligibility. FDA label CTCL following two systemic therapies; label fact, not added payer step."),
  "banner-full-1ff7d86a645bdc05": ("banner-policy-12-1557", "GL-629212", "generic zolpidem ER", "ZOLPIDEM TARTRATE TABLET ER", "conditional", "preferred", "October conditional PA: age under 6 or greater than one hypnotic in 30 days. GL-629212 names generic zolpidem/ER preferred; brand Ambien/CR nonpreferred with separate step requirements; exact brand/package unverified. Printed 30 per 30 days retained. Stage not separately labeled. FDA label boxed complex sleep behaviors; pediatric safety and efficacy not established."),
  "banner-full-d93c4badc39b2d2f": ("banner-policy-12-1557", "GL-629212", "generic zolpidem, Brand Ambien CR", "ZOLPIDEM TARTRATE TABLETS 10MG", "conditional", "preferred", "October conditional PA: age under 6 or greater than one hypnotic in 30 days. GL-629212 names generic zolpidem/ER preferred; brand Ambien/CR nonpreferred with separate step requirements; exact brand/package unverified. Printed 30 per 30 days retained. Stage not separately labeled. FDA label boxed complex sleep behaviors; pediatric safety and efficacy not established."),
  "banner-full-b41b5e9a4587cefd": ("banner-policy-12-1557", "GL-629212", "generic zolpidem, Brand Ambien CR", "ZOLPIDEM TARTRATE TABLETS 5MG", "conditional", "preferred", "October conditional PA: age under 6 or greater than one hypnotic in 30 days. GL-629212 names generic zolpidem/ER preferred; brand Ambien/CR nonpreferred with separate step requirements; exact brand/package unverified. Printed 60 per 30 days retained. Stage not separately labeled. FDA label boxed complex sleep behaviors; pediatric safety and efficacy not established."),
  "banner-full-ef9bc93d53ee9c80": ("banner-policy-12-1422", "GL-700354", "Orenitram", "TREPROSTINIL DIOLAMINE TABLET ER", "required", "not_specified", "GL-700354 effective 2026-09-01 names this product preferred for adult symptomatic PAH; initial 6 months, renewal 12 months. October PDL brand-only, PA required, preference unspecified; original flags retained. Exact package eligibility unverified. Label: swallow whole with food; avoid abrupt interruption. Distinct from inhaled treprostinil."),
  "banner-full-917087991e3a1d92": ("banner-policy-12-1422", "GL-700354", "Orenitram", "TREPROSTINIL DIOLAMINE TBER THER PACK", "required", "not_specified", "GL-700354 effective 2026-09-01 names this product preferred for adult symptomatic PAH; initial 6 months, renewal 12 months. October PDL brand-only, PA required, preference unspecified; original flags retained. Exact package eligibility unverified. Label identifies month 1/2/3 titration kits; exact month and contents of payer-listed pack unverified. Keep separate from standalone tablets."),
  "banner-full-a6ce2a3f193366dd": ("banner-policy-12-1422", "GL-700354", "Yutrepia", "TREPROSTINIL SODIUM CAPSULE", "required", "not_specified", "GL-700354 effective 2026-09-01 names this product preferred for adult symptomatic PAH; initial 6 months, renewal 12 months. October PDL brand-only, PA required, preference unspecified; original flags retained. Exact package eligibility unverified. Inhalation only: DO NOT SWALLOW capsules; use only the supplied inhaler. Distinct from Orenitram oral tablets and Tyvaso. PH-ILD indication/benefit requires separate verification; no PH-ILD authorization inferred."),
  "banner-full-910fdc030a0e440e": ("banner-policy-12-1822", "GL-325196", "Kanjinti", "TRASTUZUMAB-ANNS INJECTION", "required", "not_specified", "GL-325196 effective 2025-08-01 names Kanjinti nonpreferred; nonpreferred biosimilar requests not approved at this time, preferred Ogivri required, additional review may apply. This is the named policy restriction, not an inferred plan-wide exclusion. October PDL lists PA required with preference unspecified; retain raw flags. FDA label: IV infusion powder for reconstitution and dilution; not SC trastuzumab or an antibody-drug conjugate. Boxed cardiomyopathy, infusion reactions, pulmonary and embryo-fetal toxicity. Exact payer package and setting unverified."),
  "banner-full-8e3ddd09c2a6ceef": ("banner-policy-12-1822", "GL-325196", "Ogivri", "TRASTUZUMAB-DKST INJECTION", "required", "not_specified", "GL-325196 effective 2025-08-01 names Ogivri preferred; NCCN category 1, 2A or 2B, 12 months, stage not separately labeled. October PDL lists PA required with preference unspecified; retain raw flags. FDA label: IV infusion powder for reconstitution and dilution; not SC trastuzumab or an antibody-drug conjugate. Boxed cardiomyopathy, infusion reactions, pulmonary and embryo-fetal toxicity. Exact payer package and setting unverified."),
  "banner-full-b83161f7a9a12ddf": ("banner-policy-12-1822", "GL-325196", "Herzuma", "TRASTUZUMAB-PKRB INJECTION", "required", "not_specified", "GL-325196 effective 2025-08-01 names Herzuma nonpreferred; nonpreferred biosimilar requests not approved at this time, preferred Ogivri required, additional review may apply. This is the named policy restriction, not an inferred plan-wide exclusion. October PDL lists PA required with preference unspecified; retain raw flags. FDA label: IV infusion powder for reconstitution and dilution; not SC trastuzumab or an antibody-drug conjugate. Boxed cardiomyopathy, infusion reactions, pulmonary and embryo-fetal toxicity. Exact payer package and setting unverified."),
  "banner-full-afa717d825297dd3": ("banner-policy-12-1822", "GL-325196", "Trazimera", "TRASTUZUMAB-QYYP INJECTION", "required", "not_specified", "GL-325196 effective 2025-08-01 names Trazimera nonpreferred; nonpreferred biosimilar requests not approved at this time, preferred Ogivri required, additional review may apply. This is the named policy restriction, not an inferred plan-wide exclusion. October PDL lists PA required with preference unspecified; retain raw flags. FDA label: IV infusion powder for reconstitution and dilution; not SC trastuzumab or an antibody-drug conjugate. Boxed cardiomyopathy, infusion reactions, pulmonary and embryo-fetal toxicity. Exact payer package and setting unverified."),
  "banner-full-5b8daa67d76d4afd": ("banner-policy-12-259", "GL-99541", "generic toremifene", "TOREMIFENE CITRATE TABLETS", "required", "not_specified", "GL-99541 names brand Fareston and generic toremifene for postmenopausal metastatic ER-positive or ER-unknown breast cancer (12 months, stage not separately labeled) and NCCN initial/renewal (12 months each). No Arimidex or Aromasin-specific criteria. FDA Fareston label: oral 60 mg; boxed QT prolongation warning, contraindicated with congenital/acquired long QT or uncorrected hypokalemia/hypomagnesemia. Reference brand and exact package eligibility unverified."),
  "banner-full-2d903aad91549aef": ("banner-policy-12-1576", "GL-709190", "tramadol 50mg tablets", "TRAMADOL HCL TABLETS 50MG", "conditional", "not_specified", "October PDL: PA for more than 2 short-acting opioids in 30 days. GL-709190 names tramadol 50 mg tablets preferred; 25/75/100 mg tablets and branded oral solution are nonpreferred. Nonpreferred-only five-trial criteria do not apply to the preferred 50 mg product. Concurrent MAT DUR pp1576–1577, QL exception pp1579–1582 and MME pp1582 onward are separate reviews. FDA label: contraindicated under age 12 and under 18 after tonsillectomy/adenoidectomy; avoid adolescents at increased respiratory-depression risk. Payer pediatric quantity criteria do not establish labeled use. Exact brand/package unverified; distinct from ER."),
  "banner-full-f92ada2e9cdc655f": ("banner-policy-12-2017", "GL-660309", "Brand Xeljanz tablets", "TOFACITINIB CITRATE", "required", "preferred", "GL-660309 names brand Xeljanz immediate-release tablets preferred for RA, PsA, UC, AS and polyarticular JIA; initial and renewal 12 months each. The September 2026 FDA label requires inadequate response or intolerance to at least one TNF blocker for these indications; this is labeling, not an additional inferred payer step. Pediatric labeling is limited to PsA and pcJIA age 2 and older. IR tablets are distinct from XR tablets and oral solution. Boxed warnings apply; exact package eligibility unverified."),
  "banner-full-d4ea7eb7e9b33e7f": ("banner-policy-12-1099", "GL-611235", "generic tramadol ER tablets", "TRAMADOL HCL TABLETS ER", "required", "preferred", "GL-611235 names generic non-biphasic tramadol ER tablets preferred, distinct from Conzip and biphasic ER nonpreferred products. Ultram ER is a reference brand; exact brand eligibility, market status and package unverified. Cancer/hospice/end-of-life pain has no separately labeled authorization stage; noncancer initial and renewal are separate. Concurrent MAT DUR, quantity override and MME reviews are separate and do not establish a routine numeric formulary limit."),
  "banner-full-cec1a88dc96d5532": ("banner-policy-12-531", "GL-479199", "generic tacrolimus 0.03%", "TACROLIMUS (TOPICAL) OINTMENT", "required", "preferred", "GL-479199 names generic tacrolimus 0.03% for age 2 years and older and 0.1% for age 16 years and older; under 16 for 0.1% refers to off-label review. Label: second-line atopic dermatitis, noncontinuous treatment; under age 2 not indicated. Protopic is a reference brand, not verified brand benefit. Exact package unverified."),
  "banner-full-fe8f9d5e4dfee7b6": ("banner-policy-12-704", "GL-525287", "Elelyso", "TALIGLUCERASE ALFA", "required", "not_specified", "GL-525287 names Elelyso preferred for Type 1 Gaucher disease; October preference unspecified. Initial criteria verified; Vpriv-only prerequisites do not apply. Renewal names Eleyso (source spelling) in a mixed Type 1/3 branch; confirm exact renewal applicability with Banner. Type 3 approval not established. Label: confirmed Type 1 age 4 years and older; 200-unit vial for IV infusion after reconstitution and dilution, boxed anaphylaxis warning. Exact package unverified."),
  "banner-full-76e5b2efb93b4591": ("banner-policy-12-1557", "GL-629212", "generic temazepam", "TEMAZEPAM CAPSULES 15MG & 30MG", "conditional", "preferred", "October conditional PA: age under 6 or more than one hypnotic. GL-629212 names generic 15/30 mg preferred; brand Restoril and generic 7.5/22.5 mg are nonpreferred; their eligibility is not established by this specific row. Pediatric safety and efficacy not established in FDA labeling; a payer exception is not a labeled indication. Stage not separately labeled. Printed 30 per 30 days retained. Exact package unverified."),
  "banner-full-4d4c6a25d76989bf": ("banner-policy-12-1808", "GL-666358", "Tyenne", "TOCILIZUMAB-AAZG AUTOINJECTOR", "required", "preferred", "FDA 162 mg/0.9 mL SC solution, not IV; SC use not approved for CRS or COVID-19. GL-666358 includes SC-only SSc-ILD initial/renewal, but SSc-ILD is not a labeled indication for this biosimilar. Do not transfer IV COVID-19 criteria. Exact package unverified."),
  "banner-full-9c0e6d815920bc01": ("banner-policy-12-1808", "GL-666358", "Tyenne", "TOCILIZUMAB-AAZG SYRINGE", "required", "preferred", "FDA 162 mg/0.9 mL SC solution, not IV; SC use not approved for CRS or COVID-19. GL-666358 includes SC-only SSc-ILD initial/renewal, but SSc-ILD is not a labeled indication for this biosimilar. Do not transfer IV COVID-19 criteria. Exact package unverified."),
  "banner-full-9464979a40566984": ("banner-policy-12-1808", "GL-666358", "Tyenne", "TOCILIZUMAB-AAZG VIAL", "required", "preferred", "FDA 20 mg/mL single-dose vial for IV infusion after dilution, not SC. GL-666358 includes IV-only hospitalized COVID-19 criteria. No SC SSc-ILD criteria; label includes CRS but this chapter does not establish CRS authorization. Exact package unverified."),
  "banner-full-ad25104047d308ec": ("banner-policy-12-1808", "GL-666358", "Avtozma", "TOCILIZUMAB-ANOH SOLN AUTO-INJ", "required", "preferred", "FDA 162 mg/0.9 mL SC solution, not IV; SC use not approved for CRS or COVID-19. GL-666358 includes SC-only SSc-ILD initial/renewal, but SSc-ILD is not a labeled indication for this biosimilar. Do not transfer IV COVID-19 criteria. Exact package unverified."),
  "banner-full-2f8cff650d027225": ("banner-policy-12-1808", "GL-666358", "Avtozma", "TOCILIZUMAB-ANOH SOLN PREF SYR", "required", "preferred", "FDA 162 mg/0.9 mL SC solution, not IV; SC use not approved for CRS or COVID-19. GL-666358 includes SC-only SSc-ILD initial/renewal, but SSc-ILD is not a labeled indication for this biosimilar. Do not transfer IV COVID-19 criteria. Exact package unverified."),
  "banner-full-f4f2df53529dbd35": ("banner-policy-12-1808", "GL-666358", "Avtozma", "TOCILIZUMAB-ANOH SOLUTION", "required", "preferred", "FDA 20 mg/mL single-dose vial for IV infusion after dilution, not SC. GL-666358 includes IV-only hospitalized COVID-19 criteria. No SC SSc-ILD criteria; label includes CRS but this chapter does not establish CRS authorization. Exact package unverified."),
  "banner-full-31f510c5e7f38c18": ("banner-policy-12-1808", "GL-666358", "Tofidence", "TOCILIZUMAB-BAVI SOLUTION", "required", "preferred", "FDA 20 mg/mL single-dose vial for IV infusion after dilution, not SC. GL-666358 includes IV-only hospitalized COVID-19 criteria. No SC SSc-ILD criteria; label includes CRS but this chapter does not establish CRS authorization. Exact package unverified."),
  "banner-full-b5d2b1db3141799d": ("banner-policy-12-737", "GL-730187", "Sogroya", "SOMAPACITAN-BECO SOLN PEN-INJ", "required", "not_specified", "GL-730187 names Sogroya preferred; October formulary preference unspecified. Weekly SC somapacitan, not daily somatropin. FDA Feb 2026: pediatric GHD, SGA, Noonan and ISS age 2.5+; adult GHD. Payer ISS exclusion remains; infant criteria are not a Sogroya label indication. PWS branch does not name Sogroya. Shared payer maximum supply is not a prescribing dose. Turner, SHOX, renal insufficiency, HIV wasting and short bowel branches are not FDA-labeled Sogroya indications; verify off-label requests. Exact package unverified."),
  "banner-full-7f3830370febcc33": ("banner-policy-12-737", "GL-730187", "Genotropin cartridge", "SOMATROPIN CARTRIDGE", "required", "preferred", "October brand-only preferred PA. FDA 5 mg or 12 mg two-chamber cartridge requires compatible Genotropin pen; daily SC, distinct from Miniquick single-dose device and weekly Sogroya. Labeled pediatric GHD, PWS, SGA, Turner, ISS and adult GHD; Noonan, SHOX, renal, HIV wasting and SBS branches not labeled. PWS severe obesity/respiratory contraindications apply. Payer ISS exclusion remains; shared payer supply maximum is not prescribing dose. Exact package unverified."),
  "banner-full-9d1ec74eeb56ae29": ("banner-policy-12-737", "GL-730187", "Genotropin Miniquick", "SOMATROPIN PREFILLED SYR", "required", "preferred", "October brand-only preferred PA. FDA single-dose two-chamber device with lyophilized powder 0.2–2 mg; not a ready-to-use prefilled solution or reusable cartridge. Daily SC. Labeled pediatric GHD, PWS, SGA, Turner, ISS and adult GHD; Noonan, SHOX, renal, HIV wasting and SBS branches not labeled. PWS severe obesity/respiratory contraindications apply. Payer ISS exclusion remains; shared payer supply maximum is not prescribing dose. Exact package unverified."),
  "banner-full-1fada00875b7d8d2": ("banner-policy-12-737", "GL-730187", "Norditropin", "SOMATROPIN SOLN PEN-INJ", "required", "preferred", "October preferred PA. FDA single-patient-use ready-to-use FlexPro pens: 5, 10, 15 mg/1.5 mL and 30 mg/3 mL. Daily SC, distinct from powder devices and weekly Sogroya. Labeled pediatric GHD, Noonan, Turner, SGA, ISS, PWS and adult GHD; SHOX, renal, HIV wasting and SBS branches not labeled. PWS severe obesity/respiratory contraindications apply. Payer ISS exclusion remains; shared payer supply maximum is not prescribing dose. Exact package unverified."),
  "banner-full-b6ed7f51c1eb7ebe": ("banner-policy-12-1422", "GL-700354", "generic sildenafil suspension", "SILDENAFIL CITRATE (PULMONARY HYPERTENSION) SUSPENSION RECONSTITUTED", "conditional", "not_specified", "GL-700354 names generic sildenafil suspension preferred, adult PAH initial and renewal. October PDL states preferred under 12, PA over 12; age exactly 12 and PA criteria for ages 13–17 unresolved. Brand Revatio oral suspension FDA ages 1–17 and adults; generic labeling may omit pediatric indication. Exact product and pediatric payer criteria unverified; do not infer brand eligibility or exclusion."),
  "banner-full-60198c9988b7fac5": ("banner-policy-12-1422", "GL-700354", "generic sildenafil tablets", "SILDENAFIL CITRATE (PULMONARY HYPERTENSION) TABLETS", "required", "not_specified", "GL-700354 adult generic sildenafil PAH tablet initial 6 months and renewal 12 months. Generic named preferred; brand Revatio tablets nonpreferred, with separate nonpreferred steps. October listing VARIOUS, preference unspecified; exact brand/package and pediatric payer criteria unverified. Generic label may omit pediatric indication. Do not transfer erectile dysfunction criteria."),
  "banner-full-a16e47fcf26287e4": ("banner-policy-12-1422", "GL-700354", "generic tadalafil", "TADALAFIL (PULMONARY HYPERTENSION) TABLETS", "required", "not_specified", "GL-700354 adult generic tadalafil PAH tablet initial 6 months and renewal 12 months. Generic tadalafil/Alyq named preferred; brand Adcirca nonpreferred with separate steps. October VARIOUS listing preference unspecified; exact product/package unverified. Do not transfer erectile dysfunction or Tadliq suspension criteria."),
  "banner-full-a7f4dfa0b5da7c81": ("banner-policy-12-1530", "GL-540210", "Ruxience", "RITUXIMAB-PVVR", "required", "not_specified", "GL-540210 names Ruxience preferred in the April 2026 policy; October formulary preference is unspecified. Keep the nine indication/stage branches separate. Label: adult NHL, CLL, RA and PV; GPA/MPA age 2 years and older. The pediatric NHL/leukemia policy branch is not a labeled Ruxience indication; Waldenstrom and ITP are off-label. RA labeling also requires inadequate response to a TNF antagonist. Exact package eligibility unverified."),
  "banner-full-fb30ee751e608466": ("banner-policy-12-1798", "GL-525300", "Nplate", "ROMIPLOSTIM SOLUTION RECONSTITUTED", "required", "preferred", "GL-525300 names preferred Nplate for chronic ITP initial and renewal (12 months each) and HS-ARS (6 months, unstaged). Nonpreferred-only step does not apply to Nplate. Other thrombocytopenia and aplastic anemia branches do not name Nplate. Label confirms SC injection powder; exact eligible package unverified."),
  "banner-full-f5992d3fa1f49565": ("banner-policy-12-1896", "GL-450243", "generic sodium phenylbutyrate", "SODIUM PHENYLBUTYRATE POWDER", "required", "not_specified", "GL-450243 initial p1896 and renewal p1899. The generic trial requirement applies only to Brand Buphenyl and Pheburane, not generic sodium phenylbutyrate. Reference brand is not proof of brand-only coverage. Do not transfer glycerol phenylbutyrate initial criteria. Exact eligible package unverified."),
  "banner-full-dbcd5faa36dfde5f": ("banner-policy-12-1896", "GL-450243", "generic sodium phenylbutyrate", "SODIUM PHENYLBUTYRATE TABLET", "required", "not_specified", "GL-450243 initial p1896 and renewal p1899. The generic trial requirement applies only to Brand Buphenyl and Pheburane, not generic sodium phenylbutyrate. Reference brand is not proof of brand-only coverage. Do not transfer glycerol phenylbutyrate initial criteria. Exact eligible package unverified."),
  "banner-full-fa4f8ddffa54cfb6": ("banner-policy-12-798", "GL-371191", "sofosbuvir-velpatasvir", "SOFOSBUVIR-VELPATASVIR TABLETS", "conditional", "preferred", "October formulary authorized generic only, preferred, PA if previous DAA treatment, printed 168 / Lifetime retained. GL-371191: one lifetime course without routine PA; retreatment requires PA. Retreatment duration 12–24 weeks per policy note; stage not separately labeled. Brand Epclusa criteria do not apply to this listing. Exact package and quantity unit unverified."),
  "banner-full-0557b6b7d1ec805f": ("banner-policy-12-798", "GL-371191", "Ribavirin tablets and capsules", "RIBAVIRIN (HEPATITIS C) CAPSULES", "required", "preferred", "GL-371191 p807: chronic hepatitis C infection and use with a direct-acting agent; 12 months, authorization stage not separately labeled. The preferred DAA one-time lifetime no-PA exception is not for ribavirin. Exact eligible package unverified."),
  "banner-full-b77993fa62dc7389": ("banner-policy-12-798", "GL-371191", "Ribavirin tablets and capsules", "RIBAVIRIN (HEPATITIS C) TABLETS", "required", "preferred", "GL-371191 p807: chronic hepatitis C infection and use with a direct-acting agent; 12 months, authorization stage not separately labeled. The preferred DAA one-time lifetime no-PA exception is not for ribavirin. Exact eligible package unverified."),
  "banner-full-a385ef7908014d5f": ("banner-policy-12-963", "GL-731215", "Keytruda", "PEMBROLIZUMAB SOLUTION", "required", "not_specified", "GL-731215 cancer use supported by NCCN category 1, 2A or 2B; 12 months, stage not separately labeled. Keytruda IV 100 mg/4 mL is distinct from Keytruda Qlex subcutaneous combination. Medical PA final approval remains with the plan; exact package and setting unverified."),
  "banner-full-e532fae3af52a7f5": ("banner-policy-12-1321", "GL-731214", "Iclusig", "PONATINIB HCL TABLETS", "required", "not_specified", "GL-731214 second oncology branch names Iclusig; NCCN cancer category 1, 2A or 2B, 12 months, stage not separately labeled. Gleevec/Imkeldi-only step does not apply. Exact package and indication-specific evidence unverified."),
  "banner-full-dbd10ab6ed6cbec3": ("banner-policy-12-1321", "GL-731214", "Jakafi XR", "RUXOLITINIB PHOSPHATE TABLET ER 24HR", "required", "not_specified", "Distinct from conventional Jakafi tablets; follow label conversion instructions, not direct milligram substitution. GL-731214 names both in the cancer NCCN branch; other indications and package eligibility unverified."),
  "banner-full-201c806b5669b4d1": ("banner-policy-12-1321", "GL-731214", "Jakafi", "RUXOLITINIB PHOSPHATE TABLETS", "required", "not_specified", "Conventional tablets distinct from Jakafi XR. GL-731214 names both in the cancer NCCN branch; other indications and package eligibility unverified."),
  "banner-full-33b6c65c4a83387f": ("banner-policy-12-1321", "GL-731214", "generic sorafenib", "SORAFENIB TOSYLATE TABLETS", "required", "not_specified", "GL-731214 names brand Nexavar and generic sorafenib in the same cancer NCCN branch. The reference brand does not establish brand dispensing or preference. Exact package eligibility unverified."),
  "banner-full-127d40be02571b08": ("banner-policy-12-1805", "GL-99653", "Brand Bethkis", "TOBRAMYCIN NEBULIZED", "required", "preferred", "GL-99653 names brand Bethkis and Kitabis: CF diagnosis, 12 months, stage not separately labeled. TOBI/generic/Podhaler step and renewal branches do not apply to Bethkis. Distinct concentration from Kitabis Pak; exact eligible package unverified."),
  "banner-full-2d20172bd0ae6a5a": ("banner-policy-12-1805", "GL-99653", "Kitabis", "TOBRAMYCIN NEBULIZED", "required", "preferred", "GL-99653 names brand Bethkis and Kitabis: CF diagnosis, 12 months, stage not separately labeled. TOBI/generic/Podhaler step and renewal branches do not apply. Label specifies co-packaged PARI LC PLUS nebulizer; distinct concentration from Bethkis. Exact eligible package unverified."),
  "banner-full-697faa8211f23f28": ("banner-policy-12-1576", "GL-709190", "morphine sulfate oral solution/supp", "MORPHINE SULFATE SOLUTION", "conditional", "not_specified", "October PDL: PA for more than 2 short-acting opioids in 30 days. GL-709190 names oral morphine solution nonpreferred; separate nonpreferred review pp1577–1578, concurrent MAT DUR pp1576–1577, quantity and MME reviews pp1579 onward. Label: 20 mg/mL oral solution is reserved for opioid-tolerant adults; distinguish 2 and 4 mg/mL and avoid mg/mL dosing errors. Exact package unverified."),
  "banner-full-4710a711a65069e2": ("banner-policy-12-1576", "GL-709190", "oxycodone IR tablets/soln", "OXYCODONE HCL SOLUTION", "conditional", "not_specified", "October PDL: PA for more than 2 short-acting opioids in 30 days. GL-709190 distinguishes preferred generic IR solution and nonpreferred 100 mg/5 mL concentrate. Exact concentration and package unverified; do not transfer either preference to all solutions. Separate nonpreferred, concurrent MAT DUR, quantity and MME reviews apply where relevant."),
  "banner-full-bcd63d76ee8d2c84": ("banner-policy-12-1576", "GL-709190", "oxycodone IR tablets/soln", "OXYCODONE HCL TABLETS", "conditional", "not_specified", "October PDL: PA for more than 2 short-acting opioids in 30 days. GL-709190 names generic IR tablets preferred and brand Roxicodone nonpreferred; the reference brand does not establish brand dispensing. Separate nonpreferred, concurrent MAT DUR, quantity and MME reviews apply where relevant. Exact package and IR product unverified."),
  "banner-full-087c94375a6182f2": ("banner-policy-12-1099", "GL-611235", "generic morphine sulfate ER tablets", "MORPHINE SULFATE TABLET CONTROLLED RELEASE", "required", "preferred", "GL-611235 names generic morphine ER tablets preferred, distinct from brand MS Contin nonpreferred. Cancer/hospice/end-of-life pain and noncancer initial and renewal branches shown separately. Concurrent MAT DUR p1099, quantity p1111 and MME p1112 onward are separate reviews. Exact generic package unverified."),
  "banner-full-ef27a4dfae81f655": ("banner-policy-12-1099", "GL-611235", "Brand Oxycontin", "OXYCODONE HCL TAB 12HR DETER", "required", "not_specified", "Brand-only source row; GL-611235 names Brand Oxycontin preferred, while October PDL preference is unspecified. Other oxycodone ER listing is retained separately pending identity/package reconciliation. Concurrent MAT DUR p1099, quantity p1111 and MME p1112 onward are separate reviews. Exact package unverified."),
  "banner-full-e50339bf35f4c1a8": ("banner-policy-12-798", "GL-371191", "Pegasys", "PEGINTERFERON ALFA-2A SOLUTION", "required", "preferred", "GL-371191 pp806–807 covers chronic hepatitis C combination antiviral treatment without decompensated liver disease, 48 weeks, stage not separately labeled. FDA label also includes chronic hepatitis B; this HCV policy does not establish HBV authorization. Exact package and HBV criteria unverified."),
  "banner-full-3d7714307e911530": ("banner-policy-12-357", "GL-642203", "Fulphila", "PEGFILGRASTIM-JMDB SOLN PREF SYR", "required", "preferred", "Shared GL-642203 lists Fulphila as preferred and includes filgrastim and pegfilgrastim indication branches. Fulphila labeling supports febrile neutropenia prevention with myelosuppressive chemotherapy and explicitly excludes stem-cell mobilization. Do not transfer other products or radiation syndrome indications to this presentation; verify off-label use and exact benefit with payer. Package eligibility unverified."),
  "banner-full-c9e709fdd45fb2d7": ("banner-policy-12-357", "GL-642203", "Fylnetra", "PEGFILGRASTIM-PBBK SOLN PREF SYR", "required", "preferred", "Shared GL-642203 lists Fylnetra as preferred. FDA label additionally supports hematopoietic subsyndrome of acute radiation syndrome (April 2025); explicitly excludes stem-cell mobilization. Do not transfer filgrastim indications automatically. Verify off-label use and exact benefit with payer. Package eligibility unverified."),
  "banner-full-c221a2227136f081": ("banner-policy-12-589", "GL-620196", "generic nintedanib 100mg and 150mg capsules", "NINTEDANIB ESYLATE CAPSULE (Sandoz MFG Only)", "required", "not_specified", "GL-620196 effective May 20, 2026 explicitly prefers Sandoz generic 100 and 150 mg capsules; brand Ofev and other manufacturers are nonpreferred. October PDL names Sandoz only, with PA required and preference unspecified. IPF, SSc-ILD and progressive fibrosing ILD/PPF have distinct initial and renewal branches. Nonpreferred-only step requirements do not apply to this Sandoz option. Exact NDC eligibility is unverified."),
  "banner-full-7c0d8ee13a73e22b": ("banner-policy-12-1248", "GL-589216", "Lopressor oral solution", "METOPROLOL TARTRATE SOLUTION", "conditional", "not_specified", "October PDL prints PA required over age 10. GL-589216 effective May 1, 2026, pp1249–1250: named Lopressor oral solution branch, 12 months, stage not separately labeled; labeled or qualifying off-label indication AND failure/intolerance of generic equivalent solid oral form OR inability to swallow within that second requirement. Other-product-only Katerzia step and Subvenite continuation exception do not apply. Pediatric safety/effectiveness is not established in the FDA label. Exact package eligibility is unverified."),
  "banner-full-abc845306384483c": ("banner-policy-12-1099", "GL-611235", "generic methadone", "METHADONE HCL CONCENTRATE", "required", "not_specified", "GL-611235, effective May 19, 2026, names generic methadone tablets/concentrate/solution/tablets for oral suspension. Cancer/hospice/end-of-life pain pp1100–1101, noncancer initial pp1104–1105 and renewal pp1110–1111 are separate from MAT concurrency DUR pp1099–1100, quantity reviews pp1111–1112 and MME pp1112–1117. These do not establish OUD authorization criteria. October preference is unspecified; no new package or limit inferred. Generic Intensol labeling includes severe persistent pain and opioid addiction; Methadose concentrate labeling is for opioid addiction only. Banner's concentrate row does not identify the exact product. Do not apply pain criteria across all concentrates. Exact package and opioid use disorder (OUD) PA criteria are unverified."),
  "banner-full-9ec47e1a44d309df": ("banner-policy-12-1099", "GL-611235", "generic methadone", "METHADONE HCL SOLUTION", "required", "not_specified", "GL-611235, effective May 19, 2026, names generic methadone tablets/concentrate/solution/tablets for oral suspension. Cancer/hospice/end-of-life pain pp1100–1101, noncancer initial pp1104–1105 and renewal pp1110–1111 are separate from MAT concurrency DUR pp1099–1100, quantity reviews pp1111–1112 and MME pp1112–1117. These do not establish OUD authorization criteria. October preference is unspecified; no new package or limit inferred. Generic oral solution labeling includes severe persistent pain and opioid addiction. Banner GL-611235 pain criteria are shown only for the pain indication; exact package and OUD PA criteria are unverified."),
  "banner-full-bffe9a14c9598aaf": ("banner-policy-12-1099", "GL-611235", "generic methadone", "METHADONE HCL TABLET", "required", "not_specified", "GL-611235, effective May 19, 2026, names generic methadone tablets/concentrate/solution/tablets for oral suspension. Cancer/hospice/end-of-life pain pp1100–1101, noncancer initial pp1104–1105 and renewal pp1110–1111 are separate from MAT concurrency DUR pp1099–1100, quantity reviews pp1111–1112 and MME pp1112–1117. These do not establish OUD authorization criteria. October preference is unspecified; no new package or limit inferred. Conventional oral tablet labeling includes severe persistent pain and opioid addiction; distinct from dispersible tablets for oral suspension. Banner GL-611235 pain criteria are shown only for the pain indication; exact package and OUD PA criteria are unverified."),
  "banner-full-7f30550aa500ee70": ("banner-policy-12-1099", "GL-611235", "generic methadone", "METHADONE HCL TABLET SOLUBLE", "required", "not_specified", "GL-611235, effective May 19, 2026, names generic methadone tablets/concentrate/solution/tablets for oral suspension. Cancer/hospice/end-of-life pain pp1100–1101, noncancer initial pp1104–1105 and renewal pp1110–1111 are separate from MAT concurrency DUR pp1099–1100, quantity reviews pp1111–1112 and MME pp1112–1117. These do not establish OUD authorization criteria. October preference is unspecified; no new package or limit inferred. FDA-labeled 40 mg tablets for oral suspension are for opioid addiction treatment, not pain. Banner GL-611235 names this form in a pain guideline; do not use that as a labeled indication or apply its pain criteria automatically. Exact covered strength/package and OUD PA criteria are unverified."),
  "banner-full-a500a55a6c2da52e": ("banner-policy-12-87", "GL-109871", "memantine", "MEMANTINE HCL SOLUTION", "required", "not_specified", "GL-109871 names brand Namenda/Namenda XR and generic memantine/memantine XR (page 87): Alzheimer-type dementia diagnosis, 12 months; authorization stage is not separately labeled. Parkinson-associated dementia and Adlarity step criteria apply to other products, not this branch. Exact covered package eligibility is unverified; October preference is unspecified."),
  "banner-full-9d81da2b37ae5a9a": ("banner-policy-12-87", "GL-109871", "memantine", "MEMANTINE HCL TABLETS", "required", "not_specified", "GL-109871 names brand Namenda/Namenda XR and generic memantine/memantine XR (page 87): Alzheimer-type dementia diagnosis, 12 months; authorization stage is not separately labeled. Parkinson-associated dementia and Adlarity step criteria apply to other products, not this branch. Exact covered package eligibility is unverified; October preference is unspecified."),
  "banner-full-32585265928bf196": ("banner-policy-12-1193", "GL-715190", "Rebif", "INTERFERON BETA-1A SOLN PREF SYR", "required", "not_specified", "Rebif is named in the preferred MS initial branch (page 1193), 12 months; positive clinical response for renewal (page 1195), 12 months. October formulary preference is unspecified. Exact device/package eligibility is unverified; nonpreferred step does not apply to the named preferred branch."),
  "banner-full-5f7934d566956f29": ("banner-policy-12-737", "GL-730187", "Increlex", "MECASERMIN SOLUTION", "required", "not_specified", "Named Increlex initial (pages 764–765) and renewal (page 766) for severe primary IGF-1 deficiency or growth hormone gene deletion. Idiopathic short stature is a separate all-products benefit exclusion (page 737). Exact package eligibility is unverified; October formulary preference is unspecified."),
  "banner-full-b20b5312833f8841": ("banner-policy-12-1193", "GL-715190", "Avonex", "INTERFERON BETA-1A AUTO-INJECTOR KIT", "required", "not_specified", "Avonex is named in the preferred MS initial branch (page 1193), 12 months; positive clinical response for renewal (page 1195), 12 months. October formulary preference is unspecified. Exact device/package eligibility is unverified; nonpreferred step does not apply to the named preferred branch."),
  "banner-full-46cc6b2b57f100b3": ("banner-policy-12-1193", "GL-715190", "Avonex", "INTERFERON BETA-1A PREFILLED SYRINGE KIT", "required", "not_specified", "Avonex is named in the preferred MS initial branch (page 1193), 12 months; positive clinical response for renewal (page 1195), 12 months. October formulary preference is unspecified. Exact device/package eligibility is unverified; nonpreferred step does not apply to the named preferred branch."),
  "banner-full-fe7518236db69cb0": ("banner-policy-12-1193", "GL-715190", "Rebif", "INTERFERON BETA-1A SOLN AUTO-INJ", "required", "not_specified", "Rebif is named in the preferred MS initial branch (page 1193), 12 months; positive clinical response for renewal (page 1195), 12 months. October formulary preference is unspecified. Exact device/package eligibility is unverified; nonpreferred step does not apply to the named preferred branch."),
  "banner-full-5fb305c6fb16021c": ("banner-policy-12-721", "GL-734191", "Eligard", "LEUPROLIDE ACETATE (3 MONTH) INJECTABLE", "required", "not_specified", "Eligard is named in the advanced or metastatic prostate-cancer branch, page 734; 12 months. Preferred in guideline, preference unspecified in October row. Do not apply Lupron Depot nonpreferred step or CPP criteria."),
  "banner-full-fd34a1dfbfb6a466": ("banner-policy-12-721", "GL-734191", "Eligard", "LEUPROLIDE ACETATE (4 MONTH) KIT", "required", "not_specified", "Eligard is named in the advanced or metastatic prostate-cancer branch, page 734; 12 months. Preferred in guideline, preference unspecified in October row. Do not apply Lupron Depot nonpreferred step or CPP criteria."),
  "banner-full-01c3982354a89897": ("banner-policy-12-721", "GL-734191", "Eligard", "LEUPROLIDE ACETATE (6 MONTH) KIT", "required", "not_specified", "Eligard is named in the advanced or metastatic prostate-cancer branch, page 734; 12 months. Preferred in guideline, preference unspecified in October row. Do not apply Lupron Depot nonpreferred step or CPP criteria."),
  "banner-full-79cf3f8c029341a9": ("banner-policy-12-721", "GL-734191", "Fensolvi", "LEUPROLIDE ACETATE (CPP) (6 MONTH) KIT", "required", "not_specified", "CPP initial and renewal branches, pages 721–724; 12 months each. Preferred in guideline; October preference unspecified. Age limits for gender dysphoria in the separate October 14, 2026 policy do not apply to CPP. Other indications require their own branch; not a blanket coverage determination."),
  "banner-full-81df8d84d1f32707": ("banner-policy-12-721", "GL-734191", "Lupron Depot-Ped (1-month)", "LEUPROLIDE ACETATE (CPP) KIT", "required", "not_specified", "CPP initial and renewal branches, pages 721–724; 12 months each. Preferred in guideline; October preference unspecified. Age limits for gender dysphoria in the separate October 14, 2026 policy do not apply to CPP. Other indications require their own branch; not a blanket coverage determination."),
  "banner-full-b720c6ff93fb1ac3": ("banner-policy-12-1576", "GL-709190", "generic hydromorphone tablets", "HYDROMORPHONE HCL TABLETS", "conditional", "not_specified", "Printed PA applies to more than two short-acting opioids in 30 days. Corresponding policy branch pp1578–1579 covers dose adjustment, replacement, or documented necessity; duration up to 12 months. Generic tablets preferred in guideline; brand Dilaudid nonpreferred. Other DUR/MME/QL branches separate."),
  "banner-full-852b41b52868cf72": ("banner-policy-12-78", "GL-105169", "Intron A", "INTERFERON ALFA-2B SOLUTION", "required", "not_specified", "Intron A branch pp78–80: documentation of one of the listed indications, 12 months. No distinct renewal; do not apply Alferon N criteria. Current package availability unverified."),
  "banner-full-30fc4f26a9ae9605": ("banner-policy-12-78", "GL-105169", "Alferon N", "INTERFERON ALFA-N3 SOLUTION", "required", "not_specified", "Alferon N branch pp80–81: refractory or recurrent external HPV condylomata acuminata, documented; eight weeks. No distinct renewal; do not apply Intron A criteria. Current package availability unverified."),
  "banner-full-0272cfe23aa2123e": ("banner-policy-12-1365", "GL-105258", "Sklice", "IVERMECTIN LOTION", "required", "not_specified", "Topical head lice branch, 30 days. Generic spinosad failure requirement applies to brand Natroba only. No separate renewal; exact package eligibility unverified."),
  "banner-full-24223240af77db72": ("banner-policy-12-1321", "GL-731214", "Imbruvica", "IBRUTINIB CAPSULES", "required", "not_specified", "Oral oncology NCCN category 1, 2A or 2B; 12 months. Capsule package not specified; the separate imatinib brand step does not apply."),
  "banner-full-3562c19cd796ad78": ("banner-policy-12-1321", "GL-731214", "Imbruvica", "IBRUTINIB SUSPENSION", "required", "not_specified", "Oral oncology NCCN category 1, 2A or 2B; 12 months. Suspension package not specified; the separate imatinib brand step does not apply."),
  "banner-full-1ae1517495876514": ("banner-policy-12-811", "GL-525295", "Generic icatibant", "ICATIBANT ACETATE SOLUTION", "required", "preferred", "Preferred generic acute HAE branch, age 18 or older; 12 months. Nonpreferred-agent step does not apply. Exact package eligibility unverified."),
  "banner-full-559d389f3b8ed5ff": ("banner-policy-12-1321", "GL-731214", "Brand Gleevec, generic imatinib, Imkeldi", "IMATINIB MESYLATE TABLETS", "required", "not_specified", "Cancer NCCN category 1, 2A or 2B; 12 months. The additional generic imatinib failure requirement applies to brand Gleevec or Imkeldi requests only. This tablet row does not establish brand eligibility."),
  "banner-full-2a684512a53f1ec8": ("banner-policy-12-1321", "GL-731214", "Brand Tykerb, generic lapatinib", "LAPATINIB DITOSYLATE TABLETS", "required", "not_specified", "Named oral oncology cancer branch; NCCN category 1, 2A or 2B; 12 months. The separate imatinib step does not apply. Exact package eligibility unverified."),
  "banner-full-21719e40e35b7441": ("banner-policy-12-1321", "GL-731214", "Brand Revlimid, generic lenalidomide", "LENALIDOMIDE CAPSULE", "required", "not_specified", "Named oral oncology cancer branch; NCCN category 1, 2A or 2B; 12 months. October brand-only restriction retained; the generic mention in the guideline does not establish generic coverage."),
  "banner-full-a485618380e6e997": ("banner-policy-12-1071", "GL-427190", "Leucovorin tablets", "LEUCOVORIN CALCIUM TABLETS", "required", "not_specified", "Tablet policy: methotrexate toxicity prophylaxis, hematologic toxicity from folic acid antagonists, or documented cerebral folate deficiency. Twelve months; no separate renewal. Do not transfer to injection."),
  "banner-full-1710dea660c37719": ("banner-policy-12-468", "GL-357222", "Xiidra", "LIFITEGRAST SOLUTION", "required", "not_specified", "Xiidra preferred in guideline; October preference unspecified. Separate 12-month initial and renewal branches. Initial requires qualifying diagnosis, documented testing, lubricant trial, specialist and brand Restasis single-dose trial unless contraindicated; renewal requires positive response."),
  "banner-full-a4a289cc6cd11b2a": ("banner-policy-12-379", "GL-715189", "Linzess", "LINACLOTIDE CAPSULES", "required", "not_specified", "Separate 12-month initial and renewal. IBS-C age 7 or older; CIC age 18 or older; functional constipation age 2–17 only for 72 mcg requests. Generic lubiprostone and prucalopride steps both apply to new starts only. Exact package eligibility unverified."),
  "banner-full-015b1506addec038": ("banner-policy-12-351", "GL-356254", "famciclovir tabs", "FAMCICLOVIR TABLETS", "required", "not_specified", "Named famciclovir tablet branch, 12-month approval; separate renewal stage not specified. Do not infer brand eligibility."),
  "banner-full-b1b2bf86bd6d4857": ("banner-policy-12-1099", "GL-611235", "fentanyl transdermal", "FENTANYL PATCH 72-HOUR 12mcg, 25mcg, 50mcg, 75mcg & 100mcg", "required", "preferred", "Preferred transdermal patch rates: 12, 25, 50, 75 and 100 mcg/hr; distinct cancer/hospice and noncancer initial/renewal pathways and separate DUR, MME and quantity-review branches. This is not the transmucosal fentanyl policy."),
  "banner-full-e6a1b62352bfbc70": ("banner-policy-12-351", "GL-356254", "Foscavir inj", "FOSCARENT SODIUM", "required", "not_specified", "Named Foscavir injection criteria; CMV and compendium-supported covered indications; 12-month approval, separate renewal stage not specified. Original payer spelling retained."),
  "banner-full-d17bd539fa8f578f": ("banner-policy-12-305", "GL-734190", "Emgality 120 mg/ml", "GALCANEZUMAB-GNLM SOLN AUTO-INJ", "required", "preferred", "120 mg/mL prefilled pen for adult migraine prevention; 6-month initial and 12-month renewal. The pediatric branch is Ajovy only; the 100 mg/mL cluster headache branch is syringe only. Exact package eligibility unverified."),
  "banner-full-f4e7ff20751921ce": ("banner-policy-12-305", "GL-734190", "Emgality 100 mg/mL", "GALCANEZUMAB-GNLM SOLN PREF SYR", "required", "preferred", "Adult migraine prevention uses the 120 mg/mL syringe (6-month initial, 12-month renewal); episodic cluster headache uses the 100 mg/mL syringe (3-month initial, 12-month renewal). Exact covered strength and package not printed."),
  "banner-full-3426a5ee04aae9ee": ("banner-policy-12-351", "GL-356254", "Cytovene inj, generic ganciclovir inj", "GANCICLOVIR SODIUM", "required", "not_specified", "Named ganciclovir injection branch; CMV and compendium-supported covered indications; 12-month approval, separate renewal stage not specified."),
  "banner-full-0b18cd1fd8a34f98": ("banner-policy-12-129", "GL-620204", "granisetron tablet", "GRANISETRON HCL TABLETS", "required", "not_specified", "Tablet branch; chemotherapy, radiotherapy and postoperative prevention have different approval lengths. Granisol oral solution-only swallowing and ondansetron ODT criteria do not apply to tablets."),
  "banner-full-40d2ce2b10232236": ("banner-policy-12-1413", "GL-242221", "generic lansoprazole ODT", "LANSOPRAZOLE ORALLY DISPERSABLE TABLET (ODT)", "conditional", "preferred", "October formulary prints PA for age greater than 18; November policy distinguishes under 18 from 18 and older, including inability to swallow solid forms for the latter. Exact handling at age 18 is unresolved. No self-step through lansoprazole ODT; generic policy only."),
  "banner-full-dc42f2a6c586a16a": ("banner-policy-12-357", "GL-642203", "Nivestym", "FILGRASTIM-AAFI SOLN PREF SYR", "required", "preferred", "Nivestym is a named preferred product in the shared CSF policy. The exact syringe and indication must be checked separately; the shared policy includes off-label uses and does not establish interchangeability or package eligibility."),
  "banner-full-5446ad5479340eeb": ("banner-policy-12-357", "GL-642203", "Nivestym", "FILGRASTIM-AAFI SOLUTION", "required", "preferred", "Nivestym is a named preferred product in the shared CSF policy. The exact solution presentation and indication must be checked separately; the shared policy includes off-label uses and does not establish interchangeability or package eligibility."),
  "banner-full-73d3701a5467c050": ("banner-policy-12-357", "GL-642203", "Releuko", "FILGRASTIM-AYOW", "required", "preferred", "Releuko is a named preferred product in the shared CSF policy. The formulary does not specify its presentation; exact product, indication and package must be verified. Shared criteria include off-label uses."),
  "banner-full-f0147593c0e3df11": ("banner-policy-12-305", "GL-734190", "Ajovy", "FREMANEZUMAB-VFRM SOLN AUTO-INJ", "required", "preferred", "Migraine prevention: separate initial and renewal branches; pediatric eligibility applies only to episodic migraine for Ajovy ages 6–17 and weight at least 45 kg. Verify age-specific device labeling; the policy does not establish exact package eligibility."),
  "banner-full-1216731a2ac10ef5": ("banner-policy-12-305", "GL-734190", "Ajovy", "FREMANEZUMAB-VFRM SOLN PREF SYR", "required", "preferred", "Migraine prevention: separate initial and renewal branches; pediatric eligibility applies only to episodic migraine for Ajovy ages 6–17 and weight at least 45 kg. Verify age-specific device labeling; the policy does not establish exact package eligibility."),
  "banner-full-146f9141864dbe2a": ("banner-policy-12-1321", "GL-731214", "Brand Iressa, generic gefitinib", "GEFITINIB TABLETS", "required", "not_specified", "Named oral oncology cancer branch: NCCN category 1, 2A or 2B. Do not apply the separate imatinib step requirement. No separately stated renewal stage; exact package eligibility unverified."),
  "banner-full-dfa5cdbe92a21695": ("banner-policy-12-798", "GL-371191", "Mavyret", "GLECAPREVIR-PIBRENTASVIR PACKETS", "conditional", "preferred", "Preferred one-time lifetime course without PA; retreatment requires PA. Preserve printed packet-specific 280 per lifetime limit; do not transfer tablet quantities. Policy names Mavyret, not the exact packet package."),
  "banner-full-d4b82dd7596688b0": ("banner-policy-12-798", "GL-371191", "Mavyret", "GLECAPREVIR-PIBRENTASVIR TABLETS", "conditional", "preferred", "Preferred one-time lifetime course without PA; retreatment requires PA. Preserve printed tablet-specific 168 per lifetime limit; do not transfer packet quantities. Policy names Mavyret, not the exact tablet package."),
  "banner-full-f0dac8422def3d7b": ("banner-policy-12-1896", "GL-450243", "Brand Ravicti", "GLYCEROL PHENYLBUTYRATE LIQUID", "required", "not_specified", "Urea cycle disorder initial and renewal branches; generic glycerol phenylbutyrate alone has the additional brand Ravicti failure/intolerance requirement. October brand-only flag is retained; no separate generic eligibility inferred."),
  "banner-full-1ecc15f32d5c5aa0": ("banner-policy-12-1193", "GL-715190", "generic dalfampridine", "DALFAMPRIDINE TABLET ER 12HR", "required", "not_specified", "MS guideline: generic dalfampridine is preferred; brand Ampyra is nonpreferred. Separate initial and renewal branches. The formulary row does not specify preference; exact brand/package eligibility is unverified."),
  "banner-full-c3c6e41b892ea1d1": ("banner-policy-12-681", "GL-731220", "Bildyos", "DENOSUMAB-NXXP SOLN PREF SYR", "required", "not_specified", "Bildyos osteoporosis branch; preferred in the guideline, preference unspecified in the formulary. Separate initial and renewal criteria. The shared renewal text refers to cumulative PTH analog use, not a verified Bildyos lifetime cap."),
  "banner-full-b93efaf3c38dcf21": ("banner-policy-12-183", "GL-155386", "Austedo XR", "DEUTETRABENAZINE TABLET ER 24HR", "required", "not_specified", "Austedo XR tablet: separate tardive dyskinesia and Huntington chorea initial and renewal criteria. One active strength PA; titration-kit eligibility is not established. Preserve the XR tablet quantity limit."),
  "banner-full-13ebf33d7a321470": ("banner-policy-12-1193", "GL-715190", "generic dimethyl fumarate capsules", "DIMETHYL FUMARATE CAPSULE DELAYED RELEASE", "required", "not_specified", "Generic dimethyl fumarate capsules are preferred in the guideline, branded Tecfidera capsules and starter packs are nonpreferred. Formulary preference and exact brand/package eligibility are unverified."),
  "banner-full-c144470bcd338e8c": ("banner-policy-12-811", "GL-525295", "Kalbitor", "ECALLANTIDE SOLUTION", "required", "preferred", "Preferred acute HAE branch: age 12 or older; nonpreferred-agent step requirements do not apply. Exact package eligibility is unverified."),
  "banner-full-30fc49366041be95": ("banner-policy-12-601", "GL-642233", "Afinitor Disperz", "EVEROLIMUS SOLUBLE TABLET", "required", "not_specified", "Generic tablet for oral suspension preferred in the guideline; brand Afinitor Disperz nonpreferred. Preferred product approval is NDC-specific. Exact package eligibility is unverified; do not transfer transplant or conventional-tablet coverage."),
  'banner-full-ea0529db441446f6': ('banner-policy-12-811', 'GL-525295', 'Berinert', 'C1 ESTERASE INHIBITOR (HUMAN) SOLUTION', 'required', 'preferred', 'Acute HAE branch; product-specific age and step conditions must not be transferred.'),
  'banner-full-81af49ca953b804f': ('banner-policy-12-811', 'GL-525295', 'Cinryze, Haegarda', 'C1 ESTERASE INHIBITOR (HUMAN) SOLUTION RECONSTITUTED', 'required', 'not_specified', 'Prophylaxis branch names both; acute off-label branch names Cinryze only. Individual package eligibility is unverified.'),
  'banner-full-f1d24c36af2451fa': ('banner-policy-12-105', 'GL-545202', 'Xcopri', 'CENOBAMATE TAB THER PACK', 'required', 'not_specified', 'Named Xcopri policy; therapeutic pack not separately named.'),
  'banner-full-b2b56363cbca0ab9': ('banner-policy-12-105', 'GL-545202', 'Xcopri', 'CENOBAMATE TABLET', 'required', 'not_specified', 'Named Xcopri policy; other agents have different criteria.'),
  'banner-full-ffeacef3b187fde3': ('banner-policy-12-156', 'GL-126970', 'generic clorazepate dipotassium', 'CLORAZEPATE DIPOTASSIUM TAB 15 MG', 'conditional', 'not_specified', 'Under-six or concurrent anxiolytic DUR branches; preserve printed quantity limit.'),
  'banner-full-289217947e14a99e': ('banner-policy-12-156', 'GL-126970', 'generic clorazepate dipotassium', 'CLORAZEPATE DIPOTASSIUM TAB 3.75 MG', 'conditional', 'not_specified', 'Under-six or concurrent anxiolytic DUR branches; preserve printed quantity limit.'),
  'banner-full-08918817a94bbfa0': ('banner-policy-12-156', 'GL-126970', 'generic clorazepate dipotassium', 'CLORAZEPATE DIPOTASSIUM TAB 7.5 MG', 'conditional', 'not_specified', 'Under-six or concurrent anxiolytic DUR branches; preserve printed quantity limit.'),
 }
